    /** Network key for a URL ("globe" when unknown). Matches the host and its subdomains. */
    public static function detect(string $url): string
    {
        $host = strtolower((string) preg_replace('/^www\./', '', (string) parse_url($url, PHP_URL_HOST)));

        foreach (self::ALL as $key => $network) {
            foreach ($network['hosts'] as $h) {
                if ($host === $h || str_ends_with($host, '.'.$h)) {
                    return $key;
                }
            }
        }

        return 'globe';
    }

    public static function path(string $key): ?string
    {
        return self::ALL[$key]['path'] ?? null;
    }

    /**
     * Shape the admin form needs to detect a network and draw its icon.
     *
     * @return list<array{key: string, label: string, hosts: list<string>, path: string}>
     */
    public static function forClient(): array
    {
        $list = [];
        foreach (self::ALL as $key => $n) {
            $list[] = ['key' => $key] + $n;
        }

        return $list;
    }
}
